SELECT
    tp.process_name,
    tp.process_version,
    dfr.*
FROM
    bpm_data_form_rel dfr
        LEFT JOIN bpm_temp_process tp ON dfr.temp_process_id = tp.id


            AND parent_module_id = #{relDTO.parentModuleId}


            AND module_id = #{relDTO.moduleId}


            AND form_id = #{relDTO.formId}
